//! Cargo-driven `crypt32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x79be0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff9e000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff9e000000u64)),
        o => panic!("crypt32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:pseh", "engine:oldnames", "import:cryptnet", "import:bcrypt", "import:user32", "import:advapi32", "import:advapi32_vista", "import:msvcrt", "import:kernel32_vista", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        "x86_64" => &["engine:wine", "engine:pseh", "engine:oldnames", "import:cryptnet", "import:bcrypt", "import:user32", "import:advapi32", "import:advapi32_vista", "import:msvcrt", "import:kernel32_vista", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "aarch64" => &["engine:wine", "engine:pseh", "engine:oldnames", "import:cryptnet", "import:bcrypt", "import:user32", "import:advapi32", "import:advapi32_vista", "import:msvcrt", "import:kernel32_vista", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/crypt32",
        "dll/win32/crypt32",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "vendor/zlib/include",
        "sdk/lib/tdilib",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRYPT32_",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "_WINE",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("crypt32_shims", &["dll/win32/crypt32/base64.c", "dll/win32/crypt32/cert.c", "dll/win32/crypt32/chain.c", "dll/win32/crypt32/collectionstore.c", "dll/win32/crypt32/context.c", "dll/win32/crypt32/crl.c", "dll/win32/crypt32/ctl.c", "dll/win32/crypt32/decode.c", "dll/win32/crypt32/encode.c", "dll/win32/crypt32/filestore.c", "dll/win32/crypt32/main.c", "dll/win32/crypt32/message.c", "dll/win32/crypt32/msg.c", "dll/win32/crypt32/object.c", "dll/win32/crypt32/oid.c", "dll/win32/crypt32/pfx.c", "dll/win32/crypt32/proplist.c", "dll/win32/crypt32/protectdata.c", "dll/win32/crypt32/provstore.c", "dll/win32/crypt32/regstore.c", "dll/win32/crypt32/rootstore.c", "dll/win32/crypt32/serialize.c", "dll/win32/crypt32/sip.c", "dll/win32/crypt32/store.c", "dll/win32/crypt32/str.c", "dll/win32/crypt32/reactos/store.c", "dll/win32/crypt32/reactos/unixlib.c"])
        .rc("dll/win32/crypt32/crypt32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/crypt32/crypt32.spec", "crypt32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/cryptnet/cryptnet.spec", "cryptnet.dll", "cryptnet")
        .import_lib("dll/win32/bcrypt/bcrypt.spec", "bcrypt.dll", "bcrypt")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
